description:
Objective:
`CheckpointStore.checkpoint()` composes separation guard + serialize + DoltRepo to
turn the live SQLite campaign into a committed Dolt checkpoint; `list()` returns
the checkpoint history.

Files:
- Create: `packages/core/src/persistence/checkpoint/store.ts`
- Modify: `packages/core/src/index.ts`
- Test:   `packages/core/test/checkpoint.store.test.ts`

Steps:

1. Write the failing test `packages/core/test/checkpoint.store.test.ts`:
```ts
import { mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import { openDatabase } from '../src/persistence/db.js';
import { DoltRepo } from '../src/persistence/checkpoint/doltRepo.js';
import { CheckpointStore } from '../src/persistence/checkpoint/store.js';

const doltOk = DoltRepo.available();
function ws() {
  return mkdtempSync(join(tmpdir(), 'lw-cp-'));
}

describe.skipIf(!doltOk)('CheckpointStore.checkpoint/list', () => {
  it('checkpoints a live SQLite db and lists it', () => {
    const root = ws();
    const dbPath = join(root, 'live.db');
    const db = openDatabase(dbPath);
    db.exec('CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);');
    db.prepare('INSERT INTO meta(key, value) VALUES (?, ?)').run('hp', '10');
    db.close();

    const store = new CheckpointStore(
      join(root, 'dolt'),
      join(root, '.beads'),
    );
    const id = store.checkpoint(dbPath, 'session-close: s1');
    expect(id).toMatch(/\S+/);

    const list = store.list();
    expect(list.some((c) => c.message.includes('session-close: s1'))).toBe(true);
  });
});

describe('CheckpointStore separation guard (no dolt needed)', () => {
  it('refuses a dolt dir colocated with beads', () => {
    const root = ws();
    expect(
      () => new CheckpointStore(join(root, '.beads'), join(root, '.beads')),
    ).toThrow();
  });
});
```

2. Run it to verify FAIL.
   Command: `npx vitest run packages/core/test/checkpoint.store.test.ts`
   Expected: FAIL — module not found.

3. Create `packages/core/src/persistence/checkpoint/store.ts`:
```ts
import { openDatabase } from '../db.js';
import { assertSeparateFromBeads } from './separation.js';
import { serializeCampaign } from './serialize.js';
import { DoltRepo, type Checkpoint } from './doltRepo.js';

export class CheckpointStore {
  private readonly repo: DoltRepo;

  constructor(doltDir: string, beadsDir: string) {
    assertSeparateFromBeads(doltDir, beadsDir);
    this.repo = new DoltRepo(doltDir);
  }

  checkpoint(liveDbPath: string, message: string): string {
    const db = openDatabase(liveDbPath);
    try {
      const records = serializeCampaign(db);
      this.repo.init();
      this.repo.applySnapshot(records);
      return this.repo.commit(message);
    } finally {
      db.close();
    }
  }

  list(): Checkpoint[] {
    return this.repo.log();
  }
}
```

4. Add to `packages/core/src/index.ts` (append):
```ts
export { CheckpointStore } from './persistence/checkpoint/store.js';
```

5. Run the test to verify PASS.
   Command: `npx vitest run packages/core/test/checkpoint.store.test.ts`
   Expected: with dolt → 2 passed; without dolt → 1 passed (separation guard)
   and 1 skipped (the dolt-gated checkpoint/list test).

6. Typecheck.
   Command: `npm run build`
   Expected: exit 0.

7. Commit.
   Command: `git add -A && git commit -m "feat(e8): CheckpointStore checkpoint + list"`
